CREATE TABLE public.user_roles(user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,role text NOT NULL CHECK(role IN ('consumer','clinician')),PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.clinician_profiles(user_id uuid PRIMARY KEY,full_name text NOT NULL,professional_role text NOT NULL,clinic_name text NOT NULL DEFAULT '',country text NOT NULL,professional_email text NOT NULL,verification_status text NOT NULL DEFAULT 'unverified' CHECK(verification_status='unverified'),privacy_acknowledged_at timestamptz NOT NULL DEFAULT now(),test_only_acknowledged_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.clinician_profiles TO authenticated; GRANT ALL ON public.clinician_profiles TO service_role; ALTER TABLE public.clinician_profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.clinician_patients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL,display_name text NOT NULL,concern text NOT NULL CHECK(concern IN ('Rosacea','Acne','Post-procedure','Other')),consultation_date date NOT NULL,follow_up_date date,symptoms text NOT NULL DEFAULT '',routine text NOT NULL DEFAULT '',archived boolean NOT NULL DEFAULT false,is_test boolean NOT NULL DEFAULT true CHECK(is_test),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.clinician_patients TO authenticated; GRANT ALL ON public.clinician_patients TO service_role; ALTER TABLE public.clinician_patients ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.clinician_patient_access(patient_id uuid REFERENCES public.clinician_patients(id) ON DELETE CASCADE NOT NULL,clinician_id uuid NOT NULL,PRIMARY KEY(patient_id,clinician_id));
GRANT SELECT ON public.clinician_patient_access TO authenticated; GRANT ALL ON public.clinician_patient_access TO service_role; ALTER TABLE public.clinician_patient_access ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.clinician_consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),patient_id uuid REFERENCES public.clinician_patients(id) ON DELETE CASCADE NOT NULL,clinician_id uuid NOT NULL,scope text NOT NULL DEFAULT 'test records and synthetic photos',acknowledged_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
GRANT SELECT ON public.clinician_consents TO authenticated; GRANT ALL ON public.clinician_consents TO service_role; ALTER TABLE public.clinician_consents ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.clinician_photos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),patient_id uuid REFERENCES public.clinician_patients(id) ON DELETE CASCADE NOT NULL,uploaded_by uuid NOT NULL DEFAULT auth.uid(),storage_path text NOT NULL UNIQUE,capture_date date NOT NULL,facial_view text NOT NULL CHECK(facial_view IN ('Front','Left','Right','Other')),label text NOT NULL DEFAULT '',note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.clinician_photos TO authenticated; GRANT ALL ON public.clinician_photos TO service_role; ALTER TABLE public.clinician_photos ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.clinician_checkins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),patient_id uuid REFERENCES public.clinician_patients(id) ON DELETE CASCADE NOT NULL,recorded_by uuid NOT NULL DEFAULT auth.uid(),observation_date date NOT NULL,ratings jsonb NOT NULL DEFAULT '{}'::jsonb,observations text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.clinician_checkins TO authenticated; GRANT ALL ON public.clinician_checkins TO service_role; ALTER TABLE public.clinician_checkins ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.clinician_treatments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),patient_id uuid REFERENCES public.clinician_patients(id) ON DELETE CASCADE NOT NULL,recorded_by uuid NOT NULL DEFAULT auth.uid(),name text NOT NULL,start_date date NOT NULL,end_date date,follow_up_date date,procedure_type text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.clinician_treatments TO authenticated; GRANT ALL ON public.clinician_treatments TO service_role; ALTER TABLE public.clinician_treatments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.clinician_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),patient_id uuid REFERENCES public.clinician_patients(id) ON DELETE CASCADE NOT NULL,recorded_by uuid NOT NULL DEFAULT auth.uid(),content text NOT NULL,photo_a uuid REFERENCES public.clinician_photos(id) ON DELETE SET NULL,photo_b uuid REFERENCES public.clinician_photos(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.clinician_notes TO authenticated; GRANT ALL ON public.clinician_notes TO service_role; ALTER TABLE public.clinician_notes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.clinician_audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL DEFAULT auth.uid(),patient_id uuid,action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.clinician_audit_events TO authenticated; GRANT ALL ON public.clinician_audit_events TO service_role; ALTER TABLE public.clinician_audit_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.clinician_deletion_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),status text NOT NULL DEFAULT 'pending' CHECK(status='pending'),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.clinician_deletion_requests TO authenticated; GRANT ALL ON public.clinician_deletion_requests TO service_role; ALTER TABLE public.clinician_deletion_requests ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_clinician() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='clinician') AND EXISTS(SELECT 1 FROM public.clinician_profiles WHERE user_id=auth.uid() AND test_only_acknowledged_at IS NOT NULL) $$;
CREATE FUNCTION public.can_access_clinician_patient(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_clinician() AND EXISTS(SELECT 1 FROM public.clinician_patients p JOIN public.clinician_patient_access a ON a.patient_id=p.id JOIN public.clinician_consents c ON c.patient_id=p.id AND c.clinician_id=a.clinician_id WHERE p.id=p_id AND p.owner_id=auth.uid() AND p.is_test AND a.clinician_id=auth.uid() AND c.revoked_at IS NULL) $$;
REVOKE ALL ON FUNCTION public.is_clinician(),public.can_access_clinician_patient(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_clinician(),public.can_access_clinician_patient(uuid) TO authenticated;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY own_profile ON public.clinician_profiles FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY own_access ON public.clinician_patient_access FOR SELECT TO authenticated USING(clinician_id=auth.uid()); CREATE POLICY own_consent ON public.clinician_consents FOR SELECT TO authenticated USING(clinician_id=auth.uid());
CREATE POLICY patient_read ON public.clinician_patients FOR SELECT TO authenticated USING(public.can_access_clinician_patient(id)); CREATE POLICY patient_update ON public.clinician_patients FOR UPDATE TO authenticated USING(public.can_access_clinician_patient(id)) WITH CHECK(owner_id=auth.uid() AND is_test);
CREATE POLICY audit_read ON public.clinician_audit_events FOR SELECT TO authenticated USING(actor_id=auth.uid()); CREATE POLICY audit_insert ON public.clinician_audit_events FOR INSERT TO authenticated WITH CHECK(actor_id=auth.uid() AND public.is_clinician()); CREATE POLICY request_read ON public.clinician_deletion_requests FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY request_insert ON public.clinician_deletion_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.is_clinician() AND status='pending');
CREATE FUNCTION public.enroll_clinician(p_name text,p_role text,p_clinic text,p_country text,p_privacy boolean,p_test boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR p_privacy IS DISTINCT FROM true OR p_test IS DISTINCT FROM true THEN RAISE EXCEPTION 'Acknowledgments required'; END IF; IF length(trim(p_name)) NOT BETWEEN 1 AND 120 OR length(trim(p_country)) NOT BETWEEN 1 AND 80 OR length(p_clinic)>160 OR p_role NOT IN ('Dermatologist','Aesthetic Practitioner','Other') THEN RAISE EXCEPTION 'Invalid profile'; END IF; INSERT INTO public.clinician_profiles(user_id,full_name,professional_role,clinic_name,country,professional_email) VALUES(auth.uid(),trim(p_name),p_role,p_clinic,trim(p_country),coalesce(auth.jwt()->>'email','')) ON CONFLICT(user_id) DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'clinician') ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.enroll_clinician(text,text,text,text,boolean,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.enroll_clinician(text,text,text,text,boolean,boolean) TO authenticated;
CREATE FUNCTION public.create_clinician_patient(p_name text,p_concern text,p_date date,p_follow date,p_consent boolean,p_test boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE new_id uuid; BEGIN IF NOT public.is_clinician() OR p_consent IS DISTINCT FROM true OR p_test IS DISTINCT FROM true THEN RAISE EXCEPTION 'Test-only authorization required'; END IF; IF length(trim(p_name)) NOT BETWEEN 1 AND 120 OR p_date IS NULL THEN RAISE EXCEPTION 'Invalid patient'; END IF; INSERT INTO public.clinician_patients(owner_id,display_name,concern,consultation_date,follow_up_date) VALUES(auth.uid(),trim(p_name),p_concern,p_date,p_follow) RETURNING id INTO new_id; INSERT INTO public.clinician_patient_access(patient_id,clinician_id) VALUES(new_id,auth.uid()); INSERT INTO public.clinician_consents(patient_id,clinician_id) VALUES(new_id,auth.uid()); INSERT INTO public.clinician_audit_events(actor_id,patient_id,action) VALUES(auth.uid(),new_id,'patient_created'); RETURN new_id; END $$;
REVOKE ALL ON FUNCTION public.create_clinician_patient(text,text,date,date,boolean,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_clinician_patient(text,text,date,date,boolean,boolean) TO authenticated;
CREATE POLICY own_photos ON public.clinician_photos FOR ALL TO authenticated USING(public.can_access_clinician_patient(patient_id)) WITH CHECK(public.can_access_clinician_patient(patient_id) AND uploaded_by=auth.uid() AND storage_path LIKE auth.uid()::text || '/' || patient_id::text || '/%');
CREATE POLICY own_checkins ON public.clinician_checkins FOR ALL TO authenticated USING(public.can_access_clinician_patient(patient_id)) WITH CHECK(public.can_access_clinician_patient(patient_id) AND recorded_by=auth.uid()); CREATE POLICY own_treatments ON public.clinician_treatments FOR ALL TO authenticated USING(public.can_access_clinician_patient(patient_id)) WITH CHECK(public.can_access_clinician_patient(patient_id) AND recorded_by=auth.uid()); CREATE POLICY own_notes ON public.clinician_notes FOR ALL TO authenticated USING(public.can_access_clinician_patient(patient_id)) WITH CHECK(public.can_access_clinician_patient(patient_id) AND recorded_by=auth.uid());
CREATE FUNCTION public.validate_clinician_note() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.photo_a IS NULL) <> (NEW.photo_b IS NULL) THEN NEW.photo_a=NULL; NEW.photo_b=NULL; END IF; IF NEW.photo_a IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clinician_photos a JOIN public.clinician_photos b ON a.patient_id=b.patient_id AND a.facial_view=b.facial_view WHERE a.id=NEW.photo_a AND b.id=NEW.photo_b AND a.patient_id=NEW.patient_id AND a.id<>b.id) THEN RAISE EXCEPTION 'Matching patient and facial view required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_clinician_note BEFORE INSERT OR UPDATE ON public.clinician_notes FOR EACH ROW EXECUTE FUNCTION public.validate_clinician_note();
CREATE INDEX ON public.clinician_patients(owner_id); CREATE INDEX ON public.clinician_consents(patient_id,clinician_id); CREATE INDEX ON public.clinician_photos(patient_id); CREATE INDEX ON public.clinician_checkins(patient_id); CREATE INDEX ON public.clinician_treatments(patient_id); CREATE INDEX ON public.clinician_notes(patient_id);
CREATE POLICY clinician_photo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='clinician-test-photos' AND (storage.foldername(name))[1]=auth.uid()::text AND public.can_access_clinician_patient(((storage.foldername(name))[2])::uuid)); CREATE POLICY clinician_photo_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='clinician-test-photos' AND (storage.foldername(name))[1]=auth.uid()::text AND public.can_access_clinician_patient(((storage.foldername(name))[2])::uuid) AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp')); CREATE POLICY clinician_photo_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='clinician-test-photos' AND (storage.foldername(name))[1]=auth.uid()::text AND public.can_access_clinician_patient(((storage.foldername(name))[2])::uuid));